    @m.app.middleware("http")
    async def _v136_html(request, call_next):
        response = await call_next(request)
        if request.url.path != "/" or getattr(response, "status_code", 200) != 200:
            return response
        try:
            body = b""
            async for chunk in response.body_iterator:
                body += chunk
            html = body.decode("utf-8", errors="replace")
            if "v136-commercial-isolated-js" not in html:
                html = html.replace("</head>", parent_css + "</head>", 1).replace("</body>", parent_js + "</body>", 1)
            return HTMLResponse(html, status_code=response.status_code, headers={
                "Cache-Control": "no-store, no-cache, must-revalidate, max-age=0",
                "Pragma": "no-cache",
                "Expires": "0",
                "X-Operations-UI-Version": "V136-COMMERCIAL-ISOLATED-DEMO",
            })
        except Exception as exc:
            print(f"[V136] HTML warning: {type(exc).__name__}: {exc}", flush=True)
            return response

    m._V136_COMMERCIAL_ISOLATED_DEMO = True
    print("[V136] Demo Comercial aislado instalado: filtros y 7 pestañas independientes del portal.", flush=True)
